// Material Design icon paths (Apache-2.0), embedded so the app does not need
// the large material-icons-extended dependency for a handful of glyphs.
private fun icon(name: String, vararg paths: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f).apply {
        for (path in paths) addPath(addPathNodes(path), fill = SolidColor(Color.Black))
    }.build()

